import json,pathlib,hashlib,os,pwd,socket,datetime,subprocess,sys
p=json.loads("{\"source_commit\":\"c7714bbe09c37ead994780af53078df11c99925b\",\"files\":[{\"path\":\"web/app.js\",\"body\":\"\\\"use strict\\\";\\nconst $ = id => document.getElementById(id);\\nlet current = null;\\nasync function request(path, value) {\\n  const options = value === undefined ? {} : {method:\\\"POST\\\",headers:{\\\"Content-Type\\\":\\\"application/json\\\"},body:JSON.stringify(value)};\\n  const response = await fetch(path, options), data = await response.json();\\n  if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);\\n  return data;\\n}\\nfunction svgElement(tag, attrs, text) {\\n  const node = document.createElementNS(\\\"http://www.w3.org/2000/svg\\\", tag);\\n  for (const [k,v] of Object.entries(attrs)) node.setAttribute(k,v);\\n  if (text !== undefined) node.textContent = text;\\n  return node;\\n}\\nfunction plot(id, state, minute) {\\n  const svg = $(id); svg.replaceChildren();\\n  const X = x => 50 + (x+6)*35, Y = y => 325-y*26;\\n  for (let x=-6;x<=6;x+=2) {\\n    svg.append(svgElement(\\\"line\\\",{x1:X(x),y1:25,x2:X(x),y2:325,stroke:\\\"#293952\\\"}));\\n    svg.append(svgElement(\\\"text\\\",{x:X(x),y:348,\\\"text-anchor\\\":\\\"middle\\\"},x));\\n  }\\n  for (let y=0;y<=10;y+=2) {\\n    svg.append(svgElement(\\\"line\\\",{x1:50,y1:Y(y),x2:470,y2:Y(y),stroke:\\\"#293952\\\"}));\\n    svg.append(svgElement(\\\"text\\\",{x:34,y:Y(y)+5,\\\"text-anchor\\\":\\\"end\\\"},y));\\n  }\\n  svg.append(svgElement(\\\"text\\\",{x:255,y:377,\\\"text-anchor\\\":\\\"middle\\\"},\\\"x / nautical miles (synthetic)\\\"));\\n  svg.append(svgElement(\\\"text\\\",{x:50,y:18},\\\"y / nm • both at 10,000 fixture ft\\\"));\\n  state.aircraft.forEach((a,index) => {\\n    const color = index===0 ? \\\"#74d7cf\\\" : \\\"#eec277\\\";\\n    svg.append(svgElement(\\\"line\\\",{x1:X(a.x_nm),y1:Y(a.y_nm),x2:X(a.x_nm+a.vx_nm_min*5),y2:Y(a.y_nm+a.vy_nm_min*5),stroke:color,\\\"stroke-width\\\":3,\\\"stroke-dasharray\\\":\\\"6 5\\\"}));\\n    const x=X(a.x_nm+a.vx_nm_min*minute),y=Y(a.y_nm+a.vy_nm_min*minute);\\n    svg.append(svgElement(\\\"circle\\\",{cx:x,cy:y,r:8,fill:color}));\\n    svg.append(svgElement(\\\"text\\\",{x:Math.min(430,Math.max(60,x+12)),y:Math.max(42,y-14),fill:color},a.aircraft_id));\\n  });\\n}\\nfunction plots() {\\n  if (!current) return;\\n  const minute = Number($(\\\"minute\\\").value);\\n  $(\\\"minute-label\\\").value = `${minute.toFixed(1)} min`;\\n  plot(\\\"before\\\", current.before, minute); plot(\\\"after\\\", current.after, minute);\\n}\\nfunction render(data) {\\n  current=data; $(\\\"result\\\").hidden=false; $(\\\"export\\\").disabled=false;\\n  $(\\\"outcome\\\").textContent = data.outcome===\\\"rejected\\\" ? \\\"Rejected · no simulated actuation\\\" : \\\"Fixture accepted · simulated actuation only\\\";\\n  $(\\\"outcome\\\").className = data.outcome===\\\"rejected\\\" ? \\\"rejected\\\" : \\\"\\\";\\n  $(\\\"reason\\\").textContent = data.rejection_reason ? `Engine reason: ${data.rejection_reason}` : \\\"Exact-hash fixture approval and acknowledgement passed the engine gates.\\\";\\n  $(\\\"conflicts\\\").textContent = `Projected conflict: before ${data.before_conflict} → after ${data.after_conflict}`;\\n  $(\\\"clock\\\").textContent = `Observation ${data.simulation_clock.observed_sec}s · dispatch ${data.simulation_clock.dispatch_sec}s (synthetic)`;\\n  $(\\\"after-title\\\").textContent = data.outcome===\\\"rejected\\\" ? \\\"After rejection · unchanged world\\\" : \\\"After simulated advisory\\\";\\n  $(\\\"advisory\\\").textContent=JSON.stringify({advisory:data.advisory,advisory_hash:data.advisory_hash,fixtures:data.fixtures},null,2);\\n  $(\\\"chain\\\").textContent=`Local chain valid: ${data.audit_valid} · head ${data.audit_head}`;\\n  $(\\\"timeline\\\").replaceChildren();\\n  data.audit_events.forEach(event => {\\n    const li=document.createElement(\\\"li\\\"),title=document.createElement(\\\"strong\\\"),payload=document.createElement(\\\"pre\\\");\\n    title.textContent=`${event.seq+1}. ${event.kind}`; payload.textContent=JSON.stringify(event.payload,null,2);\\n    li.append(title,payload); $(\\\"timeline\\\").append(li);\\n  });\\n  $(\\\"minute\\\").value=0; plots();\\n}\\n$(\\\"scenario\\\").addEventListener(\\\"change\\\",()=> {\\n  $(\\\"description\\\").textContent=$(\\\"scenario\\\").selectedOptions[0].dataset.description;\\n  $(\\\"status\\\").textContent=\\\"Selection changed. Run to produce a new result; displayed result still belongs to the previous run.\\\";\\n});\\n$(\\\"minute\\\").addEventListener(\\\"input\\\",plots);\\n$(\\\"run\\\").addEventListener(\\\"click\\\",async()=> {\\n  $(\\\"run\\\").disabled=true; $(\\\"status\\\").textContent=\\\"Running local deterministic fixture…\\\";\\n  try {\\n    const data=await request(\\\"/api/run\\\",{scenario:$(\\\"scenario\\\").value,include_approval:$(\\\"approval\\\").checked,include_ack:$(\\\"ack\\\").checked});\\n    render(data); $(\\\"status\\\").textContent=`Result: ${data.label}. ${data.disclaimer}`;\\n  } catch(e) {$(\\\"status\\\").textContent=`Run failed: ${e.message}`;}\\n  finally {$(\\\"run\\\").disabled=false;}\\n});\\n$(\\\"export\\\").addEventListener(\\\"click\\\",()=> {\\n  if (!current) return;\\n  const url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:\\\"application/json\\\"}));\\n  const a=document.createElement(\\\"a\\\"); a.href=url; a.download=`towerops-${current.request.scenario}.json`; a.click();\\n  setTimeout(()=>URL.revokeObjectURL(url),1000);\\n});\\n$(\\\"replay-file\\\").addEventListener(\\\"change\\\",async()=> {\\n  const file=$(\\\"replay-file\\\").files[0]; if (!file) return;\\n  $(\\\"replay-status\\\").textContent=\\\"Replaying locally…\\\";\\n  try {\\n    if(file.size>262144) throw new Error(\\\"Export exceeds 262144 bytes\\\");\\n    const value=JSON.parse(await file.text()),reply=await request(\\\"/api/replay\\\",value);\\n    $(\\\"replay-status\\\").textContent = reply.matches ? `Replay MATCH: ${reply.outcome}. ${reply.note}` : `Replay MISMATCH: export differs from the deterministic engine result. ${reply.note}`;\\n  } catch(e) {$(\\\"replay-status\\\").textContent=`Replay rejected: ${e.message}`;}\\n});\\nrequest(\\\"/api/scenarios\\\").then(data=> {\\n  data.scenarios.forEach(item=> {const option=document.createElement(\\\"option\\\"); option.value=item.id;option.textContent=item.label;option.dataset.description=item.description;$(\\\"scenario\\\").append(option);});\\n  $(\\\"description\\\").textContent=data.scenarios[0].description;\\n  $(\\\"status\\\").textContent=\\\"Ready. Choose a case, then run the simulated fixtures.\\\";\\n}).catch(e=> {$(\\\"status\\\").textContent=`Load failed: ${e.message}`;$(\\\"run\\\").disabled=true;});\\n\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"8e1722a24196b81bad4f1c5837128d7113a96585\",\"size\":5868,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/8e1722a24196b81bad4f1c5837128d7113a96585\"},{\"path\":\"web/index.html\",\"body\":\"<!doctype html>\\n<html lang=\\\"en\\\"><head><meta charset=\\\"utf-8\\\"><meta name=\\\"viewport\\\" content=\\\"width=device-width,initial-scale=1\\\"><title>TowerOps · Synthetic explorer</title><link rel=\\\"stylesheet\\\" href=\\\"/style.css\\\"><script src=\\\"/app.js\\\" defer></script></head>\\n<body><header><p class=\\\"eyebrow\\\">TOWEROPS / LOCAL RESEARCH SIMULATION</p><h1>See the proposal. Follow the gates.</h1><p>Two fictional trajectories, one deterministic engine. Explore what happens when fixture approval, acknowledgement, timing or binding fails.</p></header>\\n<main><aside class=\\\"warning\\\"><strong>No real-world authority.</strong> Synthetic research simulation only. No live feeds, model calls, real clearances or aviation safety assurance. Every identity and approval here is a fixture.</aside>\\n<section class=\\\"controls\\\"><label for=\\\"scenario\\\">Synthetic case</label><select id=\\\"scenario\\\"></select><p id=\\\"description\\\"></p><div class=\\\"switches\\\"><label><input id=\\\"approval\\\" type=\\\"checkbox\\\" checked> Supply simulated approval fixture</label><label><input id=\\\"ack\\\" type=\\\"checkbox\\\" checked> Supply simulated acknowledgement fixture</label></div><p class=\\\"hint\\\">A selected missing-fixture case still withholds that fixture. Switches may withhold additional fixtures; they cannot bypass the engine.</p><button id=\\\"run\\\">Run synthetic case</button><button id=\\\"export\\\" disabled>Export this result (JSON)</button><label class=\\\"file-label\\\">Replay exported JSON <input id=\\\"replay-file\\\" type=\\\"file\\\" accept=\\\"application/json,.json\\\"></label><p id=\\\"replay-status\\\" role=\\\"status\\\"></p></section>\\n<p id=\\\"status\\\" role=\\\"status\\\" aria-live=\\\"polite\\\">Loading fixed scenarios…</p>\\n<section id=\\\"result\\\" hidden><h2 id=\\\"outcome\\\"></h2><p id=\\\"reason\\\"></p><div class=\\\"metrics\\\"><p id=\\\"conflicts\\\"></p><p id=\\\"clock\\\"></p></div>\\n<label for=\\\"minute\\\">Projected time <output id=\\\"minute-label\\\">0.0 min</output></label><input id=\\\"minute\\\" type=\\\"range\\\" min=\\\"0\\\" max=\\\"5\\\" step=\\\"0.1\\\" value=\\\"0\\\"><p class=\\\"hint\\\">This slider projects the constant-velocity model in minutes. It does not advance the gate's synthetic dispatch clock (seconds). Dotted paths are projections, not live tracks.</p>\\n<div class=\\\"plots\\\"><section><h3>Before proposal</h3><svg id=\\\"before\\\" viewBox=\\\"0 0 520 390\\\" role=\\\"img\\\" aria-label=\\\"Synthetic trajectories before gating\\\"></svg></section><section><h3 id=\\\"after-title\\\">After gate</h3><svg id=\\\"after\\\" viewBox=\\\"0 0 520 390\\\" role=\\\"img\\\" aria-label=\\\"Synthetic trajectories after gating\\\"></svg></section></div>\\n<section class=\\\"details\\\"><h2>Advisory &amp; fixture inputs</h2><pre id=\\\"advisory\\\"></pre><h2>Audit timeline</h2><p id=\\\"chain\\\"></p><ol id=\\\"timeline\\\"></ol></section></section>\\n<details><summary>First run &amp; replay limits</summary><p>Select “Approval + acknowledgement” and run: the engine applies the fixture advisory and projected conflict becomes false. Try “Missing acknowledgement”: the world stays unchanged. Export either result, then choose that JSON under Replay to rerun its fixed inputs and compare every output field.</p><p>The audit chain detects edits relative to the exported head. Deterministic replay checks local reproduction; neither proves authorship, external provenance, human identity, or real authority. A wholly rewritten self-consistent fixture export is not a signed receipt.</p></details></main><footer>Offline-capable loopback app · Python standard library · No SDK or subscription required</footer></body></html>\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"6bc1ac6ba66826037b292832feef79b3f96c349b\",\"size\":3396,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/6bc1ac6ba66826037b292832feef79b3f96c349b\"},{\"path\":\"web/style.css\",\"body\":\"*{box-sizing:border-box}body{overflow-wrap:anywhere;margin:0;background:#0e1726;color:#e3ebf6;font:16px/1.55 system-ui,sans-serif}header,main,footer{max-width:1120px;margin:auto;padding:24px}header{padding-top:42px}h1{font-size:clamp(28px,5vw,44px);line-height:1.15}.eyebrow{color:#74d7cf;font-size:13px;letter-spacing:2px}.warning{border-left:4px solid #eec277;background:#29283a;padding:18px;margin-bottom:24px}.controls,.details,details{background:#18253a;padding:20px;border-radius:10px}select,button,input{font:inherit}select{display:block;width:100%;max-width:540px;background:#0e1726;color:#fff;border:1px solid #8495af;border-radius:5px;padding:10px}button{background:#74d7cf;color:#0e1726;border:0;border-radius:5px;padding:10px 14px;margin:8px 8px 8px 0;cursor:pointer}button:disabled{opacity:.5;cursor:default}input[type=checkbox]{width:18px;height:18px;vertical-align:middle}.switches{display:flex;flex-wrap:wrap;gap:14px}input[type=range]{width:100%;accent-color:#74d7cf}.hint{font-size:14px;color:#b5c4da}.file-label{display:block;margin-top:12px}input[type=file]{max-width:100%;display:block;margin-top:6px}input::file-selector-button{padding:8px}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #eec277;outline-offset:3px}#outcome{padding:12px;background:#193b36}#outcome.rejected{background:#4a2835}.metrics{display:flex;flex-wrap:wrap;gap:24px}.plots{display:grid;grid-template-columns:1fr 1fr;gap:18px}.plots section{min-width:0}svg{width:100%;background:#142136;border:1px solid #485873;border-radius:8px}svg text{font:14px system-ui;fill:#d9e5f7}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}li{padding:8px 4px;border-bottom:1px solid #485873}li strong{color:#74d7cf}details{margin-top:24px}summary{cursor:pointer}footer{font-size:13px;color:#b5c4da}[hidden]{display:none!important}@media(max-width:700px){.plots{grid-template-columns:1fr}header,main,footer{padding:16px}.controls,.details{padding:14px}.switches{display:grid}h1{font-size:30px}}\\n\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"3770b65750778fecfa1ab2adc5f3ba48bafe10fb\",\"size\":2037,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/3770b65750778fecfa1ab2adc5f3ba48bafe10fb\"},{\"path\":\"EXPLORER.md\",\"body\":\"# TowerOps local synthetic scenario explorer\\n\\nResearch simulation only; fixture identities are not real authority. No live feeds, model/Strands calls, SDK dependency, real clearances, or aviation safety claim. Existing `towerops.py` is byte-for-byte unchanged from public baseline `e8fa18e`.\\n\\n## First run\\n\\nPython 3.12+ and a modern browser; **no pip install is needed for the app**.\\n\\n```sh\\npython explorer.py serve --port 8765\\n```\\n\\nOpen http://127.0.0.1:8765 . Choose **Approval + acknowledgement**, leave the two simulated-fixture boxes checked, and Run. The projected conflict changes true→false after simulated actuation. Scrub projected minutes to compare constant-velocity paths. Gate times are synthetic seconds, separate from projected minutes.\\n\\nChoose **Missing acknowledgement** and Run without reloading: rejection `ack_missing`, unchanged world, no actuation event. The displayed result and download always represent the last completed run, not an unrun selection. Withholding checkboxes cannot supply missing fixtures or bypass engine gates.\\n\\nOther fixed cases: missing approval, acknowledgement dated after dispatch cutoff (`ack_late`), stale observation, changed world hash, acknowledgement for wrong advisory, expired proposal. Every refusal retains the exact pre-gate world. Fixed identities are `FIXTURE-A`, `FIXTURE-B`, `FIXTURE-CONTROLLER-NOT-AUTHORITY`.\\n\\n## Export and replay\\n\\nExport JSON after a run. Select that file under **Replay exported JSON**: the backend reexecutes its fixed scenario and fixture switches and compares the entire result. It accepts equivalent finite JSON numbers (1001 versus 1001.0), never boolean→number coercion. Change `after.version` in a copy and replay: MISMATCH. Malformed formats/unknown scenarios are rejected. Uploaded files are not saved or used as arbitrary engine input.\\n\\nReplay is reproducibility under this local engine, not authenticity. The hash chain is not a signature or external custody anchor; someone can construct another valid fixed-fixture export. No replay result grants real authority.\\n\\nCLI (shell redirection saves real engine output):\\n\\n```sh\\npython explorer.py run approved > approved.json\\npython explorer.py run missing_ack > missing_ack.json\\npython explorer.py run approved --without-approval\\npython explorer.py replay approved.json\\n```\\n\\nReplay exits 0 for match, 1 for mismatch, 2 for malformed input.\\n\\n## Tests\\n\\nStandard-library engine/control + real HTTP suite:\\n\\n```sh\\npython -m unittest -v test_explorer\\n```\\n\\nIt exercises all eight cases × four fixture-switch combinations, exact no-actuation retention, full-export edits, JS numeric roundtrip, real HTTP run/replay, and invalid requests. No fabricated provider outputs.\\n\\nOptional actual browser acceptance:\\n\\n```sh\\npython -m pip install playwright\\npython -m playwright install chromium\\n# Linux images without browser libraries only:\\npython -m playwright install-deps chromium\\npython browser_acceptance.py\\n```\\n\\nChromium exercises all eight UI cases at desktop 1280×900 and mobile 390×844, sliders/SVG geometry, downloads, original replay, tampered replay, withheld controls, no horizontal overflow/page errors. Browser dependencies are test-only, not app dependencies. Logs/screenshots live in local `evidence/` when that directory exists.\\n\\n## HTTP scope\\n\\nBound to 127.0.0.1 only. Static routes `/`, `/app.js`, `/style.css`; GET `/api/scenarios`; POST `/api/run` with JSON `{ \\\"scenario\\\": \\\"approved\\\", \\\"include_approval\\\": true, \\\"include_ack\\\": true }`; POST `/api/replay` with a whole exported result. Fixed inputs only, 256KiB body cap, same-origin Host/Origin checks. This is a local development server, not a remotely deployed service. Ctrl+C stops it; no estate services are touched.\\n\\n## Getting the code\\n\\nEverything needed is in this repository (standard library only for the app). Either clone the branch, or apply the patch to a clean checkout of baseline `e8fa18e` (`main`):\\n\\n```sh\\ngit apply towerops-explorer-all.patch   # from a clean clone of main\\npython -m unittest -q                   # 8 tests\\npython explorer.py serve --port 8765\\n```\\n\\nA transfer zip of the same files (`towerops-explorer.zip`) runs the same way after extraction; compare its SHA-256 with the delivery report if you move it between machines.\\n\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"177f7e55002eabfee7a7f54846d063bb3dc9371f\",\"size\":4260,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/177f7e55002eabfee7a7f54846d063bb3dc9371f\"},{\"path\":\"explorer.py\",\"body\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Zero-dependency loopback-only explorer and deterministic scenario CLI.\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\\nfrom pathlib import Path\\nfrom typing import cast\\nfrom urllib.parse import urlsplit\\n\\nfrom scenarios import DISCLAIMER, SCENARIOS, replay_result, run_scenario\\n\\nROOT = Path(__file__).resolve().parent\\nMAX_BODY = 262144\\nBODY_READ_TIMEOUT = 5.0\\n\\n\\nclass Handler(BaseHTTPRequestHandler):\\n    def respond(self, status, body, content_type=\\\"application/json; charset=utf-8\\\"):\\n        raw = body if isinstance(body, bytes) else json.dumps(body, allow_nan=False).encode()\\n        self.send_response(status)\\n        self.send_header(\\\"Content-Type\\\", content_type)\\n        self.send_header(\\\"Content-Length\\\", str(len(raw)))\\n        self.send_header(\\\"Cache-Control\\\", \\\"no-store\\\")\\n        self.send_header(\\\"X-Content-Type-Options\\\", \\\"nosniff\\\")\\n        self.send_header(\\\"Content-Security-Policy\\\", \\\"default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'\\\")\\n        self.end_headers()\\n        self.wfile.write(raw)\\n\\n    def local_request(self):\\n        host = self.headers.get(\\\"Host\\\", \\\"\\\")\\n        port = cast(ThreadingHTTPServer, self.server).server_port\\n        allowed = {f\\\"127.0.0.1:{port}\\\", f\\\"localhost:{port}\\\"}\\n        origin = self.headers.get(\\\"Origin\\\")\\n        if host not in allowed or (origin is not None and origin != \\\"http://\\\" + host):\\n            self.respond(403, {\\\"error\\\": \\\"Loopback same-origin requests only\\\"})\\n            return False\\n        return True\\n\\n    def do_GET(self):\\n        if not self.local_request():\\n            return\\n        route = urlsplit(self.path).path\\n        if route == \\\"/api/scenarios\\\":\\n            self.respond(200, {\\\"disclaimer\\\": DISCLAIMER, \\\"scenarios\\\": [\\n                {\\\"id\\\": key, \\\"label\\\": label, \\\"description\\\": description}\\n                for key, (label, description) in SCENARIOS.items()]})\\n        elif route in {\\\"/\\\", \\\"/app.js\\\", \\\"/style.css\\\"}:\\n            name, mime = {\\\"/\\\": (\\\"index.html\\\", \\\"text/html\\\"), \\\"/app.js\\\": (\\\"app.js\\\", \\\"text/javascript\\\"),\\n                          \\\"/style.css\\\": (\\\"style.css\\\", \\\"text/css\\\")}[route]\\n            self.respond(200, (ROOT / \\\"web\\\" / name).read_bytes(), mime + \\\"; charset=utf-8\\\")\\n        else:\\n            self.respond(404, {\\\"error\\\": \\\"Not found\\\"})\\n\\n    def do_POST(self):\\n        if not self.local_request():\\n            return\\n        if self.path not in {\\\"/api/run\\\", \\\"/api/replay\\\"}:\\n            self.respond(404, {\\\"error\\\": \\\"Not found\\\"})\\n            return\\n        try:\\n            if self.headers.get_all(\\\"Transfer-Encoding\\\") is not None:\\n                self.respond(400, {\\\"error\\\": \\\"Transfer-Encoding is not supported; use Content-Length\\\"})\\n                return\\n            lengths = self.headers.get_all(\\\"Content-Length\\\", [])\\n            if not lengths:\\n                self.respond(411, {\\\"error\\\": \\\"Content-Length is required\\\"})\\n                return\\n            if len(lengths) != 1:\\n                self.respond(400, {\\\"error\\\": \\\"Provide exactly one Content-Length\\\"})\\n                return\\n            length_text = lengths[0].strip(\\\" \\\\t\\\")\\n            if not length_text.isascii() or not length_text.isdecimal():\\n                self.respond(400, {\\\"error\\\": \\\"Content-Length must contain ASCII decimal digits\\\"})\\n                return\\n            # Compare decimal text before conversion, including arbitrarily\\n            # many leading zeroes, without Python's integer-string limit.\\n            length_text = length_text.lstrip(\\\"0\\\") or \\\"0\\\"\\n            maximum = str(MAX_BODY)\\n            if (length_text == \\\"0\\\" or len(length_text) > len(maximum)\\n                    or (len(length_text) == len(maximum) and length_text > maximum)):\\n                self.respond(413, {\\\"error\\\": \\\"Body must be between 1 and 262144 bytes\\\"})\\n                return\\n            length = int(length_text)\\n            if self.headers.get(\\\"Content-Type\\\", \\\"\\\").split(\\\";\\\")[0] != \\\"application/json\\\":\\n                self.respond(415, {\\\"error\\\": \\\"Use application/json\\\"})\\n                return\\n            previous_timeout = self.connection.gettimeout()\\n            self.connection.settimeout(BODY_READ_TIMEOUT)\\n            try:\\n                raw = self.rfile.read(length)\\n            except TimeoutError:\\n                self.respond(408, {\\\"error\\\": \\\"Timed out waiting for the complete request body\\\"})\\n                return\\n            finally:\\n                self.connection.settimeout(previous_timeout)\\n            if len(raw) != length:\\n                self.respond(400, {\\\"error\\\": \\\"Request body is shorter than Content-Length\\\"})\\n                return\\n            def reject_constant(value):\\n                raise ValueError(\\\"Non-finite JSON is not supported\\\")\\n            value = json.loads(raw, parse_constant=reject_constant)\\n            if self.path == \\\"/api/replay\\\":\\n                result = replay_result(value)\\n            else:\\n                if not isinstance(value, dict) or set(value) != {\\\"scenario\\\", \\\"include_approval\\\", \\\"include_ack\\\"}:\\n                    raise ValueError(\\\"Provide scenario and both fixture switches\\\")\\n                if not isinstance(value[\\\"scenario\\\"], str):\\n                    raise ValueError(\\\"Scenario must be a string\\\")\\n                result = run_scenario(**value)\\n            self.respond(200, result)\\n        except (ValueError, TypeError, KeyError, RecursionError) as exc:\\n            self.respond(400, {\\\"error\\\": str(exc)[:200]})\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=DISCLAIMER)\\n    commands = parser.add_subparsers(dest=\\\"command\\\", required=True)\\n    serve = commands.add_parser(\\\"serve\\\", help=\\\"Loopback-only browser UI\\\")\\n    serve.add_argument(\\\"--port\\\", type=int, default=8765)\\n    run = commands.add_parser(\\\"run\\\", help=\\\"Export a fixed synthetic case as JSON\\\")\\n    run.add_argument(\\\"scenario\\\", choices=SCENARIOS)\\n    run.add_argument(\\\"--without-approval\\\", action=\\\"store_true\\\")\\n    run.add_argument(\\\"--without-ack\\\", action=\\\"store_true\\\")\\n    replay = commands.add_parser(\\\"replay\\\", help=\\\"Recompute and compare a local JSON export\\\")\\n    replay.add_argument(\\\"file\\\", type=Path)\\n    args = parser.parse_args()\\n    if args.command == \\\"serve\\\":\\n        with ThreadingHTTPServer((\\\"127.0.0.1\\\", args.port), Handler) as server:\\n            print(f\\\"Synthetic explorer: http://127.0.0.1:{server.server_port}\\\\n{DISCLAIMER}\\\", flush=True)\\n            try:\\n                server.serve_forever()\\n            except KeyboardInterrupt:\\n                pass\\n    elif args.command == \\\"run\\\":\\n        print(json.dumps(run_scenario(args.scenario, not args.without_approval, not args.without_ack), indent=2))\\n    else:\\n        try:\\n            if args.file.stat().st_size > MAX_BODY:\\n                raise ValueError(\\\"Export exceeds 262144 bytes\\\")\\n            result = replay_result(json.loads(args.file.read_text()))\\n        except (ValueError, TypeError) as exc:\\n            parser.exit(2, str(exc) + \\\"\\\\n\\\")\\n        print(json.dumps(result, indent=2))\\n        if not result[\\\"matches\\\"]:\\n            raise SystemExit(1)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"mode\":\"100755\",\"type\":\"blob\",\"sha\":\"897ddf219cb5be863ff89318d1bf8b22a08e3e2f\",\"size\":7141,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/897ddf219cb5be863ff89318d1bf8b22a08e3e2f\"},{\"path\":\"scenarios.py\",\"body\":\"\\\"\\\"\\\"Fixed research fixtures: no live inputs, authority, or model calls.\\\"\\\"\\\"\\nfrom dataclasses import asdict, replace\\nfrom typing import Any\\n\\nfrom towerops import (\\n    Ack,\\n    AdvisoryPlanner,\\n    Aircraft,\\n    Approval,\\n    ControlRoom,\\n    GateRejected,\\n    SafetyPolicy,\\n    WorldState,\\n)\\n\\nDISCLAIMER = \\\"Synthetic research simulation only. Fixture identities, not real approval or authority. Not operational ATC, aviation assurance, or live aircraft control.\\\"\\nSCENARIOS = {\\n    \\\"approved\\\": (\\\"Approval + acknowledgement\\\", \\\"Both exact-hash fixtures arrive before simulated dispatch.\\\"),\\n    \\\"missing_approval\\\": (\\\"Missing approval\\\", \\\"The engine must refuse simulated actuation without its approval fixture.\\\"),\\n    \\\"missing_ack\\\": (\\\"Missing acknowledgement\\\", \\\"Approval alone does not authorize the simulated transition.\\\"),\\n    \\\"late_ack\\\": (\\\"Late acknowledgement\\\", \\\"Receipt is dated after the simulated dispatch cutoff; the engine rejects ack_late.\\\"),\\n    \\\"stale_state\\\": (\\\"Stale observation\\\", \\\"The observation is older than the engine's ten-second freshness limit.\\\"),\\n    \\\"stale_binding\\\": (\\\"Changed world binding\\\", \\\"World version changes after proposal; its hash no longer matches.\\\"),\\n    \\\"wrong_ack\\\": (\\\"Wrong advisory acknowledgement\\\", \\\"Receipt binds a different advisory hash.\\\"),\\n    \\\"expired\\\": (\\\"Expired proposal\\\", \\\"Dispatch occurs after the proposal's eight-second validity window.\\\"),\\n}\\n\\n\\ndef run_scenario(scenario: str, include_approval: bool = True, include_ack: bool = True) -> dict[str, Any]:\\n    if scenario not in SCENARIOS:\\n        raise ValueError(\\\"Unknown synthetic scenario\\\")\\n    if type(include_approval) is not bool or type(include_ack) is not bool:\\n        raise ValueError(\\\"Fixture switches must be booleans\\\")\\n    policy = SafetyPolicy()\\n    source = WorldState(1, 1001.0, (\\n        Aircraft(\\\"FIXTURE-A\\\", -5.0, 0.0, 10000.0, 1.0, 0.0),\\n        Aircraft(\\\"FIXTURE-B\\\", 5.0, 0.0, 10000.0, -1.0, 0.0),\\n    ))\\n    advisory = AdvisoryPlanner(policy).plan(source, now=1002.0)[0]\\n    state = replace(source, version=2) if scenario == \\\"stale_binding\\\" else source\\n    now = {\\\"stale_state\\\": 1012.0, \\\"expired\\\": 1010.5}.get(scenario, 1002.5)\\n    approval = Approval(advisory.advisory_hash, \\\"approve\\\", 1002.2, \\\"FIXTURE-CONTROLLER-NOT-AUTHORITY\\\")\\n    ack = Ack(\\\"f\\\" * 64 if scenario == \\\"wrong_ack\\\" else advisory.advisory_hash,\\n              \\\"accepted\\\", 1002.8 if scenario == \\\"late_ack\\\" else 1002.4)\\n    if not include_approval or scenario == \\\"missing_approval\\\":\\n        approval = None\\n    if not include_ack or scenario == \\\"missing_ack\\\":\\n        ack = None\\n    room = ControlRoom(policy)\\n    room.audit.append(\\\"fixture_proposal\\\", {\\\"scenario\\\": scenario, \\\"source_world_hash\\\": source.world_hash,\\n                                         \\\"advisory\\\": asdict(advisory), \\\"simulation_only\\\": True})\\n    after, reason = state, None\\n    try:\\n        after = room.apply(state, advisory, approval, ack, now)\\n    except GateRejected as exc:\\n        reason = exc.reason\\n    return {\\n        \\\"format\\\": \\\"towerops.synthetic-explorer.v1\\\", \\\"disclaimer\\\": DISCLAIMER,\\n        \\\"request\\\": {\\\"scenario\\\": scenario, \\\"include_approval\\\": include_approval, \\\"include_ack\\\": include_ack},\\n        \\\"label\\\": SCENARIOS[scenario][0], \\\"description\\\": SCENARIOS[scenario][1],\\n        \\\"simulation_clock\\\": {\\\"dispatch_sec\\\": now, \\\"observed_sec\\\": state.observed_at,\\n                             \\\"projection_horizon_min\\\": policy.horizon_min},\\n        \\\"policy\\\": asdict(policy), \\\"before\\\": state.to_dict(), \\\"after\\\": after.to_dict(),\\n        \\\"before_world_hash\\\": state.world_hash, \\\"after_world_hash\\\": after.world_hash,\\n        \\\"advisory\\\": asdict(advisory), \\\"advisory_hash\\\": advisory.advisory_hash,\\n        \\\"fixtures\\\": {\\\"approval\\\": asdict(approval) if approval else None, \\\"ack\\\": asdict(ack) if ack else None},\\n        \\\"outcome\\\": \\\"simulated_actuation\\\" if reason is None else \\\"rejected\\\",\\n        \\\"rejection_reason\\\": reason, \\\"before_conflict\\\": policy.state_has_conflict(state),\\n        \\\"after_conflict\\\": policy.state_has_conflict(after),\\n        \\\"audit_events\\\": room.audit.events, \\\"audit_head\\\": room.audit.head,\\n        \\\"audit_valid\\\": room.audit.verify(room.audit.events),\\n    }\\n\\n\\ndef json_equivalent(expected: Any, actual: Any) -> bool:\\n    import math\\n    if type(expected) in (int, float) and type(actual) in (int, float):\\n        return (type(actual) is int or math.isfinite(actual)) and expected == actual\\n    if type(expected) is not type(actual):\\n        return False\\n    if isinstance(expected, dict):\\n        return expected.keys() == actual.keys() and all(json_equivalent(v, actual[k]) for k, v in expected.items())\\n    if isinstance(expected, list):\\n        return len(expected) == len(actual) and all(json_equivalent(a, b) for a, b in zip(expected, actual))\\n    return expected == actual\\n\\n\\ndef replay_result(value: Any) -> dict[str, Any]:\\n    \\\"\\\"\\\"Rerun fixed inputs and compare *all* output, not merely a self-consistent chain.\\n\\n    This proves reproducibility under this local code, NOT provenance/authority.\\n    \\\"\\\"\\\"\\n    if not isinstance(value, dict) or value.get(\\\"format\\\") != \\\"towerops.synthetic-explorer.v1\\\":\\n        raise ValueError(\\\"Unsupported export format\\\")\\n    request = value.get(\\\"request\\\")\\n    if not isinstance(request, dict) or set(request) != {\\\"scenario\\\", \\\"include_approval\\\", \\\"include_ack\\\"}:\\n        raise ValueError(\\\"Malformed fixture request\\\")\\n    if not isinstance(request[\\\"scenario\\\"], str):\\n        raise TypeError(\\\"Scenario must be a string\\\")\\n    expected = run_scenario(**request)\\n    # JSON clients serialize 1001.0 as 1001. Accept equivalent finite numbers,\\n    # but never coerce booleans, strings, containers, or field presence.\\n    matches = json_equivalent(expected, value)\\n    return {\\\"matches\\\": matches, \\\"audit_valid\\\": expected[\\\"audit_valid\\\"],\\n            \\\"outcome\\\": expected[\\\"outcome\\\"], \\\"rejection_reason\\\": expected[\\\"rejection_reason\\\"],\\n            \\\"expected_audit_head\\\": expected[\\\"audit_head\\\"],\\n            \\\"note\\\": \\\"Local deterministic reproduction only; not a signature, provenance proof, or authority.\\\"}\\n\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"33b5703d2ce0d4177c50f05536e3f2715c8bea3b\",\"size\":5989,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/33b5703d2ce0d4177c50f05536e3f2715c8bea3b\"},{\"path\":\"towerops.py\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"0b03cee708cdff5cbacd148633def31f4e9414c5\",\"size\":19684,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/0b03cee708cdff5cbacd148633def31f4e9414c5\",\"body\":\"from __future__ import annotations\\n\\nimport hashlib\\nimport json\\nimport math\\nfrom collections.abc import Iterable\\nfrom dataclasses import asdict, dataclass, replace\\nfrom fractions import Fraction\\nfrom typing import Any\\n\\nZERO_HASH = \\\"0\\\" * 64\\n\\n\\ndef canonical_bytes(value: Any) -> bytes:\\n    return json.dumps(value, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), ensure_ascii=False).encode(\\\"utf-8\\\")\\n\\n\\ndef sha256_obj(value: Any) -> str:\\n    return hashlib.sha256(canonical_bytes(value)).hexdigest()\\n\\n\\ndef _finite_number(value: Any) -> bool:\\n    return type(value) is int or (type(value) is float and math.isfinite(value))\\n\\n\\ndef _finite_time(value: Any) -> bool:\\n    return _finite_number(value)\\n\\n\\nclass GateRejected(RuntimeError):\\n    def __init__(self, reason: str):\\n        super().__init__(reason)\\n        self.reason = reason\\n\\n\\n@dataclass(frozen=True)\\nclass Aircraft:\\n    aircraft_id: str\\n    x_nm: float\\n    y_nm: float\\n    altitude_ft: float\\n    vx_nm_min: float\\n    vy_nm_min: float\\n    climb_ft_min: float = 0.0\\n\\n    def projected(self, minutes: float) -> Aircraft:\\n        return replace(\\n            self,\\n            x_nm=self.x_nm + self.vx_nm_min * minutes,\\n            y_nm=self.y_nm + self.vy_nm_min * minutes,\\n            altitude_ft=self.altitude_ft + self.climb_ft_min * minutes,\\n        )\\n\\n\\n@dataclass(frozen=True)\\nclass WorldState:\\n    version: int\\n    observed_at: float\\n    aircraft: tuple[Aircraft, ...]\\n\\n    def __post_init__(self) -> None:\\n        # Keep the exact membership checked below even if a caller supplied a\\n        # mutable sequence or a one-shot iterator instead of a native tuple.\\n        object.__setattr__(self, \\\"aircraft\\\", tuple(self.aircraft))\\n        # Aircraft ids key every id-based operation (get, replace_aircraft,\\n        # advisory_safe's target exclusion). Duplicate ids would silently\\n        # break those invariants — e.g. advisory_safe skips id-twins, letting\\n        # an advisory that collides with a twin pass the gate — so malformed\\n        # states are rejected at construction instead of failing open.\\n        seen: set[str] = set()\\n        for aircraft in self.aircraft:\\n            if aircraft.aircraft_id in seen:\\n                raise ValueError(f\\\"duplicate aircraft_id: {aircraft.aircraft_id!r}\\\")\\n            seen.add(aircraft.aircraft_id)\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return {\\n            \\\"version\\\": self.version,\\n            \\\"observed_at\\\": self.observed_at,\\n            \\\"aircraft\\\": [asdict(a) for a in sorted(self.aircraft, key=lambda x: x.aircraft_id)],\\n        }\\n\\n    @property\\n    def world_hash(self) -> str:\\n        return sha256_obj(self.to_dict())\\n\\n    def get(self, aircraft_id: str) -> Aircraft:\\n        for aircraft in self.aircraft:\\n            if aircraft.aircraft_id == aircraft_id:\\n                return aircraft\\n        raise KeyError(aircraft_id)\\n\\n    def replace_aircraft(self, updated: Aircraft, observed_at: float) -> WorldState:\\n        values = tuple(updated if a.aircraft_id == updated.aircraft_id else a for a in self.aircraft)\\n        return WorldState(version=self.version + 1, observed_at=observed_at, aircraft=values)\\n\\n\\n@dataclass(frozen=True)\\nclass Advisory:\\n    aircraft_id: str\\n    world_hash: str\\n    set_vx_nm_min: float\\n    set_vy_nm_min: float\\n    set_climb_ft_min: float\\n    issued_at: float\\n    expires_at: float\\n    rationale: str\\n\\n    @property\\n    def advisory_hash(self) -> str:\\n        return sha256_obj(asdict(self))\\n\\n\\n@dataclass(frozen=True)\\nclass Approval:\\n    advisory_hash: str\\n    decision: str\\n    approved_at: float\\n    approver: str\\n\\n\\n@dataclass(frozen=True)\\nclass Ack:\\n    advisory_hash: str\\n    status: str\\n    acknowledged_at: float\\n\\n\\nclass AuditLog:\\n    def __init__(self) -> None:\\n        self.events: list[dict[str, Any]] = []\\n\\n    def append(self, kind: str, payload: dict[str, Any]) -> str:\\n        prev = self.events[-1][\\\"event_hash\\\"] if self.events else ZERO_HASH\\n        event = {\\\"seq\\\": len(self.events), \\\"kind\\\": kind, \\\"payload\\\": payload, \\\"prev_hash\\\": prev}\\n        event_hash = hashlib.sha256(prev.encode(\\\"ascii\\\") + b\\\"\\\\n\\\" + canonical_bytes(event)).hexdigest()\\n        event[\\\"event_hash\\\"] = event_hash\\n        self.events.append(event)\\n        return event_hash\\n\\n    @property\\n    def head(self) -> str:\\n        return self.events[-1][\\\"event_hash\\\"] if self.events else ZERO_HASH\\n\\n    @staticmethod\\n    def verify(events: Iterable[dict[str, Any]]) -> bool:\\n        prev = ZERO_HASH\\n        for expected_seq, raw in enumerate(events):\\n            event = dict(raw)\\n            claimed = event.pop(\\\"event_hash\\\", None)\\n            if event.get(\\\"seq\\\") != expected_seq or event.get(\\\"prev_hash\\\") != prev:\\n                return False\\n            actual = hashlib.sha256(prev.encode(\\\"ascii\\\") + b\\\"\\\\n\\\" + canonical_bytes(event)).hexdigest()\\n            if claimed != actual:\\n                return False\\n            prev = actual\\n        return True\\n\\n\\n@dataclass(frozen=True)\\nclass SafetyPolicy:\\n    min_horizontal_nm: float = 5.0\\n    min_vertical_ft: float = 1000.0\\n    horizon_min: float = 5.0\\n    sample_step_min: float = 0.5\\n    max_state_age_sec: float = 10.0\\n    max_speed_nm_min: float = 6.0\\n    max_climb_ft_min: float = 3000.0\\n\\n    @staticmethod\\n    def _linear_abs_unsafe_interval(offset: float, rate: float, limit: float, horizon: float) -> tuple[float, float] | None:\\n        \\\"\\\"\\\"Open time interval in [0,horizon] where abs(offset + rate*t) < limit.\\\"\\\"\\\"\\n        if limit <= 0.0 or horizon < 0.0:\\n            return None\\n        if rate == 0.0:\\n            return (0.0, horizon) if abs(offset) < limit else None\\n        t1, t2 = (-limit - offset) / rate, (limit - offset) / rate\\n        lo, hi = sorted((t1, t2))\\n        lo, hi = max(0.0, lo), min(horizon, hi)\\n        return (lo, hi) if lo < hi else None\\n\\n    @staticmethod\\n    def _horizontal_unsafe_interval(dx: float, dy: float, dvx: float, dvy: float, limit: float, horizon: float) -> tuple[float, float] | None:\\n        \\\"\\\"\\\"Open time interval in [0,horizon] where horizontal separation is below limit.\\\"\\\"\\\"\\n        if limit <= 0.0 or horizon < 0.0:\\n            return None\\n        a = dvx * dvx + dvy * dvy\\n        b = 2.0 * (dx * dvx + dy * dvy)\\n        c = dx * dx + dy * dy - limit * limit\\n        if a == 0.0:\\n            return (0.0, horizon) if c < 0.0 else None\\n        disc = b * b - 4.0 * a * c\\n        if disc <= 0.0:\\n            return None\\n        root = math.sqrt(disc)\\n        lo, hi = sorted(((-b - root) / (2.0 * a), (-b + root) / (2.0 * a)))\\n        lo, hi = max(0.0, lo), min(horizon, hi)\\n        return (lo, hi) if lo < hi else None\\n\\n    def _pair_conflict(self, a: Aircraft, b: Aircraft) -> bool:\\n        # Fail closed: a non-finite field (NaN/inf) means the separation is\\n        # unknown, so the pair is treated as conflicting rather than safe.\\n        # Without this, NaN comparisons silently evaluate False and an\\n        # aircraft with unknown state could pass the safety gate.\\n        for value in (\\n            a.x_nm, a.y_nm, a.altitude_ft, a.vx_nm_min, a.vy_nm_min, a.climb_ft_min,\\n            b.x_nm, b.y_nm, b.altitude_ft, b.vx_nm_min, b.vy_nm_min, b.climb_ft_min,\\n        ):\\n            if not _finite_number(value):\\n                return True\\n        h = self._horizontal_unsafe_interval(\\n            a.x_nm - b.x_nm, a.y_nm - b.y_nm,\\n            a.vx_nm_min - b.vx_nm_min, a.vy_nm_min - b.vy_nm_min,\\n            self.min_horizontal_nm, self.horizon_min,\\n        )\\n        if h is None:\\n            return False\\n        v = self._linear_abs_unsafe_interval(\\n            a.altitude_ft - b.altitude_ft, a.climb_ft_min - b.climb_ft_min,\\n            self.min_vertical_ft, self.horizon_min,\\n        )\\n        if v is None:\\n            return False\\n        return max(h[0], v[0]) < min(h[1], v[1])\\n\\n    def state_has_conflict(self, state: WorldState) -> bool:\\n        values = list(state.aircraft)\\n        return any(self._pair_conflict(values[i], values[j]) for i in range(len(values)) for j in range(i + 1, len(values)))\\n\\n    def conflicting_aircraft(self, state: WorldState) -> list[Aircraft]:\\n        \\\"\\\"\\\"Aircraft that participate in at least one conflicting pair, sorted by id.\\n\\n        The planner only proposes maneuvers for aircraft in this set: moving an\\n        uninvolved aircraft can never open separation for a conflict pair, and\\n        the gate alone cannot tell that an advisory is aimed at the wrong target.\\n        \\\"\\\"\\\"\\n        values = sorted(state.aircraft, key=lambda x: x.aircraft_id)\\n        return [\\n            candidate\\n            for candidate in values\\n            if any(self._pair_conflict(candidate, other) for other in values if other.aircraft_id != candidate.aircraft_id)\\n        ]\\n\\n    def advisory_safe(self, state: WorldState, advisory: Advisory) -> bool:\\n        if advisory.world_hash != state.world_hash:\\n            return False\\n        # A singleton has no pairwise checks to reject unknown candidate fields.\\n        if not all(_finite_number(value) for value in (\\n            advisory.set_vx_nm_min, advisory.set_vy_nm_min, advisory.set_climb_ft_min,\\n        )):\\n            return False\\n        if math.hypot(advisory.set_vx_nm_min, advisory.set_vy_nm_min) > self.max_speed_nm_min:\\n            return False\\n        if abs(advisory.set_climb_ft_min) > self.max_climb_ft_min:\\n            return False\\n        try:\\n            target = state.get(advisory.aircraft_id)\\n        except KeyError:\\n            return False\\n        if not all(_finite_number(value) for value in (target.x_nm, target.y_nm, target.altitude_ft)):\\n            return False\\n        candidate = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)\\n        return all(not self._pair_conflict(candidate, other) for other in state.aircraft if other.aircraft_id != candidate.aircraft_id)\\n\\n\\nclass AdvisoryPlanner:\\n    \\\"\\\"\\\"Deterministic synthetic planner; model adapters may propose alternatives, never bypass the frozen gate.\\\"\\\"\\\"\\n\\n    def __init__(self, policy: SafetyPolicy) -> None:\\n        self.policy = policy\\n\\n    def _maneuver_candidates(self, target: Aircraft) -> Iterable[tuple[float, float, float]]:\\n        \\\"\\\"\\\"Yield (vx, vy, climb) candidates in fixed priority order.\\n\\n        Lateral-only variants come first to preserve the historical resolution\\n        preference; climb and speed variants follow so vertical-convergence\\n        conflicts (unresolvable laterally) still get a bounded safe advisory.\\n        Combined lateral+climb variants are tried last. Duplicates are skipped.\\n        Every candidate is still admitted only through ``advisory_safe``.\\n        \\\"\\\"\\\"\\n        seen: set[tuple[float, float, float]] = set()\\n\\n        def _emit(vx: float, vy: float, climb: float) -> Iterable[tuple[float, float, float]]:\\n            key = (vx, vy, climb)\\n            if key not in seen:\\n                seen.add(key)\\n                yield key\\n\\n        speed_limit = self.policy.max_speed_nm_min\\n        vx = target.vx_nm_min\\n        if _finite_number(vx) and abs(vx) <= speed_limit:\\n            remaining_sq = max(0.0, speed_limit * speed_limit - vx * vx)\\n            vy_max = math.sqrt(remaining_sq)\\n            # Keep the boundary candidate inside policy after float rounding.\\n            while math.hypot(vx, vy_max) > speed_limit and vy_max > 0.0:\\n                vy_max = math.nextafter(vy_max, 0.0)\\n            old_menu = (2.0, -2.0, 3.0, -3.0, 0.0)\\n            lateral_values = (\\n                *(max(-vy_max, min(vy_max, vy)) for vy in old_menu),\\n                vy_max, -vy_max,\\n                vy_max / 2.0, -vy_max / 2.0,\\n                vy_max / 4.0, -vy_max / 4.0,\\n            )\\n            for vy in lateral_values:\\n                yield from _emit(vx, vy, target.climb_ft_min)\\n        for climb in (0.0, 1000.0, -1000.0, 2000.0, -2000.0, 3000.0, -3000.0):\\n            yield from _emit(target.vx_nm_min, target.vy_nm_min, climb)\\n        for dvx in (1.0, -1.0, 2.0, -2.0):\\n            yield from _emit(target.vx_nm_min + dvx, target.vy_nm_min, target.climb_ft_min)\\n        for vy in (2.0, -2.0, 3.0, -3.0):\\n            # Combined loop caps climb at +/-2000 (inside the gate's 3000 bound);\\n            # wider climb setpoints are already covered by the climb-only loop above.\\n            for climb in (0.0, 1000.0, -1000.0, 2000.0, -2000.0):\\n                yield from _emit(target.vx_nm_min, vy, climb)\\n\\n    def plan(self, state: WorldState, now: float) -> list[Advisory]:\\n        if not self.policy.state_has_conflict(state):\\n            return []\\n        # Target selection: only aircraft that actually participate in a\\n        # conflict are maneuvered, highest id first (the historical default\\n        # target was always the highest id). Aiming at an uninvolved aircraft\\n        # produced gate-safe but useless advisories while the real conflict\\n        # persisted, so the planner now never targets outside the conflict set.\\n        targets = list(reversed(self.policy.conflicting_aircraft(state)))\\n        for target in targets:\\n            for vx, vy, climb in self._maneuver_candidates(target):\\n                advisory = Advisory(\\n                    aircraft_id=target.aircraft_id,\\n                    world_hash=state.world_hash,\\n                    set_vx_nm_min=vx,\\n                    set_vy_nm_min=vy,\\n                    set_climb_ft_min=climb,\\n                    issued_at=now,\\n                    expires_at=now + 8.0,\\n                    rationale=\\\"synthetic projected-separation recovery\\\",\\n                )\\n                if self.policy.advisory_safe(state, advisory):\\n                    return [advisory]\\n        return []\\n\\n\\nclass ControlRoom:\\n    def __init__(self, policy: SafetyPolicy | None = None) -> None:\\n        self.policy = policy or SafetyPolicy()\\n        self.audit = AuditLog()\\n\\n    def _fresh(self, state: WorldState, now: float) -> None:\\n        if not _finite_time(state.observed_at) or not _finite_time(now):\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_state_time\\\"})\\n            raise GateRejected(\\\"invalid_state_time\\\")\\n        if state.observed_at > now:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"future_state\\\", \\\"world_hash\\\": state.world_hash})\\n            raise GateRejected(\\\"future_state\\\")\\n        if type(now) is int or type(state.observed_at) is int:\\n            age = Fraction(now) - Fraction(state.observed_at)\\n        else:\\n            age = now - state.observed_at\\n        if age > self.policy.max_state_age_sec:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"stale_state\\\", \\\"world_hash\\\": state.world_hash})\\n            raise GateRejected(\\\"stale_state\\\")\\n\\n    def screen_batch(self, state: WorldState, advisories: list[Advisory], now: float) -> list[str]:\\n        self._fresh(state, now)\\n        by_aircraft: dict[str, set[str]] = {}\\n        for advisory in advisories:\\n            by_aircraft.setdefault(advisory.aircraft_id, set()).add(advisory.advisory_hash)\\n        if any(len(hashes) > 1 for hashes in by_aircraft.values()):\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"conflicting_recommendations\\\", \\\"world_hash\\\": state.world_hash})\\n            raise GateRejected(\\\"conflicting_recommendations\\\")\\n        hashes: list[str] = []\\n        for advisory in advisories:\\n            if not _finite_time(advisory.issued_at) or not _finite_time(advisory.expires_at):\\n                self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_advisory_time\\\", \\\"aircraft_id\\\": advisory.aircraft_id})\\n                raise GateRejected(\\\"invalid_advisory_time\\\")\\n            if advisory.issued_at < state.observed_at or advisory.issued_at > now or advisory.expires_at < advisory.issued_at:\\n                self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_advisory_time\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n                raise GateRejected(\\\"invalid_advisory_time\\\")\\n            if advisory.world_hash != state.world_hash:\\n                self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"world_hash_mismatch\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n                raise GateRejected(\\\"world_hash_mismatch\\\")\\n            if now > advisory.expires_at:\\n                self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"expired_advisory\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n                raise GateRejected(\\\"expired_advisory\\\")\\n            if not self.policy.advisory_safe(state, advisory):\\n                self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"unsafe_advisory\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n                raise GateRejected(\\\"unsafe_advisory\\\")\\n            hashes.append(advisory.advisory_hash)\\n        self.audit.append(\\\"screen_pass\\\", {\\\"world_hash\\\": state.world_hash, \\\"advisory_hashes\\\": hashes})\\n        return hashes\\n\\n    def apply(self, state: WorldState, advisory: Advisory, approval: Approval | None, ack: Ack | None, now: float) -> WorldState:\\n        self.screen_batch(state, [advisory], now)\\n        if approval is None or approval.advisory_hash != advisory.advisory_hash or approval.decision != \\\"approve\\\":\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"human_approval_required\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"human_approval_required\\\")\\n        if not _finite_time(approval.approved_at):\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_approval_time\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"invalid_approval_time\\\")\\n        if approval.approved_at < advisory.issued_at or approval.approved_at > advisory.expires_at or approval.approved_at > now:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_approval_time\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"invalid_approval_time\\\")\\n        self.audit.append(\\\"approval\\\", asdict(approval))\\n        if ack is None:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"ack_missing\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"ack_missing\\\")\\n        if ack.advisory_hash != advisory.advisory_hash or ack.status != \\\"accepted\\\":\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"ack_invalid\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"ack_invalid\\\")\\n        if not _finite_time(ack.acknowledged_at):\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_ack_time\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"invalid_ack_time\\\")\\n        if ack.acknowledged_at < approval.approved_at or ack.acknowledged_at < advisory.issued_at:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"invalid_ack_time\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"invalid_ack_time\\\")\\n        if ack.acknowledged_at > advisory.expires_at or ack.acknowledged_at > now:\\n            self.audit.append(\\\"reject\\\", {\\\"reason\\\": \\\"ack_late\\\", \\\"advisory_hash\\\": advisory.advisory_hash})\\n            raise GateRejected(\\\"ack_late\\\")\\n        self.audit.append(\\\"ack\\\", asdict(ack))\\n        target = state.get(advisory.aircraft_id)\\n        updated = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)\\n        new_state = state.replace_aircraft(updated, observed_at=now)\\n        self.audit.append(\\\"simulated_actuation\\\", {\\n            \\\"advisory_hash\\\": advisory.advisory_hash,\\n            \\\"before_world_hash\\\": state.world_hash,\\n            \\\"after_world_hash\\\": new_state.world_hash,\\n        })\\n        return new_state\\n\\n\\ndef baseline_apply_unchecked(state: WorldState, advisory: Advisory, now: float) -> WorldState:\\n    target = state.get(advisory.aircraft_id)\\n    updated = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)\\n    return state.replace_aircraft(updated, observed_at=now)\\n\"},{\"path\":\"test_explorer.py\",\"body\":\"import copy\\nimport http.client\\nimport json\\nimport threading\\nimport unittest\\n\\nfrom explorer import Handler, ThreadingHTTPServer\\nfrom scenarios import SCENARIOS, replay_result, run_scenario\\nfrom towerops import AuditLog, canonical_bytes\\n\\nEXPECTED = {\\\"approved\\\": None, \\\"missing_approval\\\": \\\"human_approval_required\\\", \\\"missing_ack\\\": \\\"ack_missing\\\",\\n            \\\"late_ack\\\": \\\"ack_late\\\", \\\"stale_state\\\": \\\"stale_state\\\", \\\"stale_binding\\\": \\\"world_hash_mismatch\\\",\\n            \\\"wrong_ack\\\": \\\"ack_invalid\\\", \\\"expired\\\": \\\"expired_advisory\\\"}\\n\\n\\nclass ScenarioTests(unittest.TestCase):\\n    def test_all_cases_and_fixture_switches(self):\\n        for case in SCENARIOS:\\n            for approval in (False, True):\\n                for ack in (False, True):\\n                    with self.subTest(case=case, approval=approval, ack=ack):\\n                        result = run_scenario(case, approval, ack)\\n                        self.assertTrue(result[\\\"before_conflict\\\"])\\n                        self.assertTrue(AuditLog.verify(result[\\\"audit_events\\\"]))\\n                        self.assertTrue(replay_result(result)[\\\"matches\\\"])\\n                        actuation = [e for e in result[\\\"audit_events\\\"] if e[\\\"kind\\\"] == \\\"simulated_actuation\\\"]\\n                        if case == \\\"approved\\\" and approval and ack:\\n                            self.assertEqual(result[\\\"outcome\\\"], \\\"simulated_actuation\\\")\\n                            self.assertFalse(result[\\\"after_conflict\\\"])\\n                            self.assertEqual(len(actuation), 1)\\n                            self.assertEqual(result[\\\"after\\\"][\\\"version\\\"], result[\\\"before\\\"][\\\"version\\\"] + 1)\\n                        else:\\n                            self.assertEqual(result[\\\"outcome\\\"], \\\"rejected\\\")\\n                            self.assertEqual(result[\\\"before\\\"], result[\\\"after\\\"])\\n                            self.assertEqual(actuation, [])\\n                        if approval and ack:\\n                            self.assertEqual(result[\\\"rejection_reason\\\"], EXPECTED[case])\\n\\n    def test_replay_checks_whole_export(self):\\n        for case in SCENARIOS:\\n            original = run_scenario(case)\\n            for field in (\\\"after\\\", \\\"audit_events\\\", \\\"disclaimer\\\", \\\"audit_head\\\", \\\"outcome\\\"):\\n                with self.subTest(case=case, field=field):\\n                    changed = copy.deepcopy(original)\\n                    if field == \\\"after\\\":\\n                        changed[field][\\\"version\\\"] += 1\\n                    elif field == \\\"audit_events\\\":\\n                        changed[field][0][\\\"payload\\\"][\\\"simulation_only\\\"] = False\\n                    else:\\n                        changed[field] = \\\"tampered\\\"\\n                    self.assertFalse(replay_result(changed)[\\\"matches\\\"])\\n        changed = run_scenario(\\\"approved\\\")\\n        changed[\\\"audit_valid\\\"] = 1\\n        self.assertFalse(replay_result(changed)[\\\"matches\\\"])\\n\\n    def test_javascript_numeric_roundtrip(self):\\n        original = run_scenario(\\\"approved\\\")\\n        def integers(value):\\n            if type(value) is float and value.is_integer():\\n                return int(value)\\n            if isinstance(value, dict):\\n                return {k: integers(v) for k, v in value.items()}\\n            if isinstance(value, list):\\n                return [integers(v) for v in value]\\n            return value\\n        self.assertTrue(replay_result(integers(original))[\\\"matches\\\"])\\n        changed = copy.deepcopy(original)\\n        changed[\\\"before\\\"][\\\"aircraft\\\"][0][\\\"vx_nm_min\\\"] += 0.001\\n        self.assertFalse(replay_result(changed)[\\\"matches\\\"])\\n\\n    def test_no_baseline_changes_or_nondeterminism(self):\\n        self.assertEqual(canonical_bytes(run_scenario(\\\"approved\\\")), canonical_bytes(run_scenario(\\\"approved\\\")))\\n\\n    def test_invalid_input(self):\\n        for value in (None, [], {}, {\\\"format\\\": \\\"invalid\\\"}):\\n            with self.subTest(value=value), self.assertRaises(ValueError):\\n                replay_result(value)\\n        with self.assertRaises(ValueError):\\n            run_scenario(\\\"unknown\\\")\\n        with self.assertRaises(ValueError):\\n            run_scenario(\\\"approved\\\", 1, True)  # type: ignore[arg-type]\\n\\n\\nclass HTTPTests(unittest.TestCase):\\n    @classmethod\\n    def setUpClass(cls):\\n        cls.server = ThreadingHTTPServer((\\\"127.0.0.1\\\", 0), Handler)\\n        cls.thread = threading.Thread(target=cls.server.serve_forever, daemon=True)\\n        cls.thread.start()\\n\\n    @classmethod\\n    def tearDownClass(cls):\\n        cls.server.shutdown()\\n        cls.server.server_close()\\n        cls.thread.join()\\n\\n    def request(self, method, path, value=None, headers=None, raw=None):\\n        connection = http.client.HTTPConnection(\\\"127.0.0.1\\\", self.server.server_port, timeout=5)\\n        body = json.dumps(value) if value is not None else raw\\n        supplied = {\\\"Content-Type\\\": \\\"application/json\\\"}\\n        supplied.update(headers or {})\\n        connection.request(method, path, body, supplied)\\n        response = connection.getresponse()\\n        status, content, response_headers = response.status, response.read(), dict(response.getheaders())\\n        connection.close()\\n        return status, content, response_headers\\n\\n    def test_real_run_export_replay(self):\\n        status, content, _ = self.request(\\\"GET\\\", \\\"/api/scenarios\\\")\\n        self.assertEqual(status, 200)\\n        self.assertEqual(len(json.loads(content)[\\\"scenarios\\\"]), len(SCENARIOS))\\n        for case in SCENARIOS:\\n            with self.subTest(case=case):\\n                status, content, _ = self.request(\\\"POST\\\", \\\"/api/run\\\", {\\\"scenario\\\": case, \\\"include_approval\\\": True, \\\"include_ack\\\": True})\\n                self.assertEqual(status, 200)\\n                exported = json.loads(content)\\n                self.assertEqual(exported[\\\"rejection_reason\\\"], EXPECTED[case])\\n                status, content, _ = self.request(\\\"POST\\\", \\\"/api/replay\\\", exported)\\n                self.assertEqual(status, 200)\\n                self.assertTrue(json.loads(content)[\\\"matches\\\"])\\n                exported[\\\"after\\\"][\\\"version\\\"] += 1\\n                self.assertFalse(json.loads(self.request(\\\"POST\\\", \\\"/api/replay\\\", exported)[1])[\\\"matches\\\"])\\n\\n    def test_static_assets_and_unknown_routes(self):\\n        for path in (\\\"/\\\", \\\"/app.js\\\", \\\"/style.css\\\"):\\n            status, content, headers = self.request(\\\"GET\\\", path)\\n            self.assertEqual(status, 200)\\n            self.assertGreater(len(content), 100)\\n            self.assertIn(\\\"frame-ancestors 'none'\\\", headers[\\\"Content-Security-Policy\\\"])\\n        for path in (\\\"/towerops.py\\\", \\\"/../LICENSE\\\", \\\"/.git/config\\\"):\\n            self.assertEqual(self.request(\\\"GET\\\", path)[0], 404)\\n\\n    def test_invalid_requests_fail(self):\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", {\\\"scenario\\\": \\\"approved\\\"})[0], 400)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"not-json\\\")[0], 400)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw='{\\\"x\\\": NaN}')[0], 400)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"[]\\\")[0], 400)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"{}\\\", headers={\\\"Content-Type\\\": \\\"text/plain\\\"})[0], 415)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"x\\\" * 262145)[0], 413)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"{}\\\")[0], 400)\\n        self.assertEqual(self.request(\\\"GET\\\", \\\"/\\\", headers={\\\"Host\\\": \\\"foreign.invalid\\\"})[0], 403)\\n        self.assertEqual(self.request(\\\"POST\\\", \\\"/api/run\\\", raw=\\\"{}\\\", headers={\\\"Origin\\\": \\\"https://foreign.invalid\\\"})[0], 403)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main(verbosity=2)\\n\",\"mode\":\"100644\",\"type\":\"blob\",\"sha\":\"51f7de9067a733d11649684d799417d66c84c36d\",\"size\":7460,\"url\":\"https://api.github.com/repos/Jacob-Met/TowerOps/git/blobs/51f7de9067a733d11649684d799417d66c84c36d\"}],\"test\":\"\\\"use strict\\\";\\nconst assert = require(\\\"node:assert/strict\\\");\\nconst fs = require(\\\"node:fs\\\");\\nconst path = require(\\\"node:path\\\");\\nconst vm = require(\\\"node:vm\\\");\\nconst test = require(\\\"node:test\\\");\\n\\nconst appPath = process.argv[2] || path.join(__dirname, \\\"..\\\", \\\"web\\\", \\\"app.js\\\");\\nconst app = fs.readFileSync(appPath, \\\"utf8\\\");\\nconst tick = () => new Promise(resolve => setImmediate(resolve));\\nfunction deferred() {\\n  let resolve, reject;\\n  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });\\n  return {promise, resolve, reject};\\n}\\nfunction file(value, overrides = {}) {\\n  return {name: \\\"fixture.json\\\", size: 20, text: async () => JSON.stringify(value), ...overrides};\\n}\\nfunction reply(matches, note = \\\"current note\\\") {\\n  return {matches, outcome: \\\"rejected\\\", note};\\n}\\nfunction response(data) {\\n  return {ok: true, json: async () => data};\\n}\\nasync function harness() {\\n  const nodes = new Map();\\n  function node(id) {\\n    if (!nodes.has(id)) nodes.set(id, {\\n      id, textContent: \\\"\\\", value: \\\"\\\", disabled: false, files: [], dataset: {},\\n      children: [], listeners: {}, selectedOptions: [{dataset: {description: \\\"fixture\\\"}}],\\n      addEventListener(kind, listener) { this.listeners[kind] = listener; },\\n      append(...items) { this.children.push(...items); },\\n      replaceChildren(...items) { this.children = items; },\\n      setAttribute() {},\\n    });\\n    return nodes.get(id);\\n  }\\n  const calls = [];\\n  const context = vm.createContext({\\n    document: {getElementById: node, createElement: () => node(Symbol()),\\n      createElementNS: () => node(Symbol())},\\n    fetch: (url, options) => {\\n      if (url === \\\"/api/scenarios\\\") return Promise.resolve(response({\\n        scenarios: [{id: \\\"approved\\\", label: \\\"Approved\\\", description: \\\"fixture\\\"}],\\n      }));\\n      assert.equal(url, \\\"/api/replay\\\");\\n      const gate = deferred();\\n      calls.push({url, body: JSON.parse(options.body), gate});\\n      return gate.promise;\\n    },\\n    console, setTimeout, URL, Blob,\\n  });\\n  vm.runInContext(app, context, {filename: appPath});\\n  await tick();\\n  const unrelated = () => JSON.stringify([...nodes].filter(([id]) =>\\n    typeof id === \\\"string\\\" && id !== \\\"replay-file\\\" && id !== \\\"replay-status\\\")\\n    .map(([id, n]) => [id, n.textContent, n.value, n.disabled, n.children.length]));\\n  const before = unrelated();\\n  return {\\n    calls, context,\\n    choose(selected) {\\n      node(\\\"replay-file\\\").files = selected ? [selected] : [];\\n      return node(\\\"replay-file\\\").listeners.change();\\n    },\\n    status: () => node(\\\"replay-status\\\").textContent,\\n    preserve: () => {\\n      assert.equal(unrelated(), before, \\\"replay does not alter other controls\\\");\\n      assert.equal(vm.runInContext(\\\"current\\\", context), null, \\\"displayed run stays unchanged\\\");\\n    },\\n  };\\n}\\n\\ntest(\\\"current match and mismatch keep their existing complete messages\\\", async () => {\\n  const h = await harness();\\n  let pending = h.choose(file({id: \\\"match\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(true))); await pending;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  pending = h.choose(file({id: \\\"mismatch\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(false))); await pending;\\n  assert.equal(h.status(), \\\"Replay MISMATCH: export differs from the deterministic engine result. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded file read does not send a replay or replace the newer verdict\\\", async () => {\\n  const h = await harness(), oldRead = deferred();\\n  const old = h.choose(file({}, {text: () => oldRead.promise}));\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(false, \\\"new file\\\"))); await fresh;\\n  const accepted = h.status();\\n  oldRead.resolve(JSON.stringify({id: \\\"old\\\"})); await tick();\\n  // Settle an obsolete request if the original source issued it, without hanging the test.\\n  for (const call of h.calls.slice(1)) call.gate.resolve(response(reply(true, \\\"old file\\\")));\\n  await old;\\n  assert.equal(h.calls.length, 1, \\\"old read must not reach the backend\\\");\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded file read error cannot replace current pending or completed status\\\", async () => {\\n  const h = await harness(), oldRead = deferred();\\n  const old = h.choose(file({}, {text: () => oldRead.promise}));\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  oldRead.reject(new Error(\\\"old read error\\\")); await old;\\n  assert.equal(h.status(), \\\"Replaying locally…\\\");\\n  h.calls[0].gate.resolve(response(reply(true))); await fresh;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded HTTP response cannot replace a newer mismatch\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(false, \\\"new file\\\"))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.resolve(response(reply(true, \\\"old file\\\"))); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded JSON body cannot replace a newer rejection\\\", async () => {\\n  const h = await harness(), body = deferred();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  h.calls[0].gate.resolve({ok: true, json: () => body.promise}); await tick();\\n  await h.choose(file({}, {text: async () => \\\"{\\\"}));\\n  const accepted = h.status();\\n  assert.match(accepted, /^Replay rejected:/);\\n  body.resolve(reply(true, \\\"old body\\\")); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a superseded transport error cannot replace a newer match\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  const fresh = h.choose(file({id: \\\"new\\\"})); await tick();\\n  h.calls[1].gate.resolve(response(reply(true))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.reject(new Error(\\\"old network error\\\")); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"clearing selection retires an in-flight response and clears its status\\\", async () => {\\n  const h = await harness();\\n  const old = h.choose(file({id: \\\"old\\\"})); await tick();\\n  await h.choose(null);\\n  assert.equal(h.status(), \\\"\\\");\\n  h.calls[0].gate.resolve(response(reply(true))); await old;\\n  assert.equal(h.status(), \\\"\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"selecting the same File again retires its earlier request\\\", async () => {\\n  const h = await harness(), same = file({id: \\\"same\\\"});\\n  const old = h.choose(same); await tick();\\n  const fresh = h.choose(same); await tick();\\n  h.calls[1].gate.resolve(response(reply(false, \\\"latest attempt\\\"))); await fresh;\\n  const accepted = h.status();\\n  h.calls[0].gate.resolve(response(reply(true, \\\"earlier attempt\\\"))); await old;\\n  assert.equal(h.status(), accepted);\\n  h.preserve();\\n});\\n\\ntest(\\\"a current oversize or read failure refuses, and an explicit corrected selection recovers\\\", async () => {\\n  const h = await harness();\\n  await h.choose(file({}, {size: 262145, text: () => { throw new Error(\\\"must not read\\\"); }}));\\n  assert.equal(h.status(), \\\"Replay rejected: Export exceeds 262144 bytes\\\");\\n  assert.equal(h.calls.length, 0);\\n  await h.choose(file({}, {text: async () => { throw new Error(\\\"current read error\\\"); }}));\\n  assert.equal(h.status(), \\\"Replay rejected: current read error\\\");\\n  const fresh = h.choose(file({id: \\\"corrected\\\"})); await tick();\\n  h.calls[0].gate.resolve(response(reply(true))); await fresh;\\n  assert.equal(h.status(), \\\"Replay MATCH: rejected. current note\\\");\\n  h.preserve();\\n});\\n\\ntest(\\\"a current backend refusal retains the existing error display\\\", async () => {\\n  const h = await harness();\\n  const pending = h.choose(file({id: \\\"current\\\"})); await tick();\\n  h.calls[0].gate.resolve({ok: false, status: 400, json: async () => ({error: \\\"current server refusal\\\"})});\\n  await pending;\\n  assert.equal(h.status(), \\\"Replay rejected: current server refusal\\\");\\n  h.preserve();\\n});\\n\"}")
